test('configured area policy has explicit fixed slots/respawn and blocks every player-vs-player damage source',()=>{const p=createConfiguredAreaPolicy(validateWorldConfig(config()).worlds.w1);assert.deepEqual(p.enemyPopulation({kind:'scrapling',role:'ordinary'},0),{desired:1,respawnSeconds:300});assert.equal(p.enemyPopulation({kind:'scrapling',role:'echo'},100).respawnSeconds,120);assert.equal(p.damageAllowed({}, {kind:'player'}, {kind:'player'}),false);assert.equal(p.damageAllowed({},null,{kind:'player'}),true);});
test('all32 supported timing/location combinations preserve HP/resources/progression and explicitly cancel activity',()=>{
 const identity=selection('human','female','priest'),initial=structuredClone(configured.codec.fresh({characterId:'restore-source',identity}));initial.world='w3';setQuestChapter(initial.progress.quests,3);Object.assign(initial.survival,{hp:37,resource:17,cooldowns:{'crown-burst':{startAge:2,endRemaining:58}},gcd:{startAge:.25,endRemaining:.75},history:{combatAge:1,spendAge:2,attackAge:3,nextSwingRemaining:1}});Object.assign(initial.survival.statuses,{stunRemaining:2,slowRemaining:4,slowPct:.5,rustRemaining:3,rust:5,absorbRemaining:5,absorb:20,absorbMax:30,warded:true,blessingRemaining:7,encounterBlessing:true});initial.activity.seated=true;initial.activity.village=true;initial.activity.controlsLocked=true;initial.activity.channel={kind:'recall',startAge:.5,endRemaining:1.5};initial.activity.motion.pushRemaining=.4;initial.activity.motion.pushX=7;const before=structuredClone(initial);let count=0;
 for(const cooldowns of ['pause','elapse'])for(const statuses of ['pause','elapse'])for(const death of ['pause','elapse'])for(const history of ['pause','elapse'])for(const location of ['saved','arrival']){const choice={...restore,cooldowns,statuses,death,history,location},policy=createConfiguredRestorePolicy(choice,configured.catalog),out=prepareRestore(initial,10,policy);assert.equal(out.survival.hp,37);assert.equal(out.survival.resource,17);assert.deepEqual(out.progress,initial.progress);assert.deepEqual(out.survival.cooldowns['crown-burst'],cooldowns==='pause'?{startAge:2,endRemaining:58}:{startAge:12,endRemaining:48});assert.equal(out.survival.statuses.rust,statuses==='pause'?5:0);assert.equal(out.survival.statuses.encounterBlessing,true);assert.equal(out.survival.history.combatAge,history==='pause'?1:11);assert.equal(out.activity.seated,false);assert.equal(out.activity.channel,null);assert.equal(out.activity.motion.pushX,0);const arrival=configured.catalog.get('w3').publicDefinition.pois.arrival;assert.deepEqual(out.location,location==='saved'?initial.location:{...arrival.position,yaw:arrival.yaw});count++;}assert.equal(count,32);assert.deepEqual(initial,before);
});
test('explicit dead timer elapse preserves dead HP/resources until actual core next-tick respawn and pause does not age',()=>{
 const initial=structuredClone(configured.codec.fresh({characterId:'dead-policy',identity:selection()}));Object.assign(initial.survival,{alive:false,hp:0,resource:0,respawnRemaining:3.6});for(const death of ['pause','elapse']){const out=prepareRestore(initial,10,createConfiguredRestorePolicy({...restore,death},configured.catalog));assert.equal(out.survival.alive,false);assert.equal(out.survival.hp,0);assert.equal(out.survival.respawnRemaining,death==='pause'?3.6:0);const world=configured.catalog.get('w1'),area=createArea({id:`restore-${death}`,definition:world.publicDefinition,query:world.query,policy:world.policy,seed:world.seed,actionData:world.actionData,context:{mode:'public',pvp:'disabled',members:[]},limits:{eventCount:4096,inputCommandsPerTick:32,timers:256,projectiles:256}}),reservation=area.reserveAdmission(initial.character,'spawn',0),staged=area.stageRestoredArrival(reservation,initial,out),ref=area.activateRestoredArrival(staged.token);area.step(new Map());assert.equal(area.services.playerByCharacter(initial.character).unit.alive,death==='elapse');if(death==='pause')assert.equal(area.services.getUnit(ref).hp,0);area.dispose();}
});
test('restore rejects unsupported policies/faults/overflow without mutating captured data',()=>{const c=configured.codec.fresh({characterId:'restore-fault',identity:selection()}),before=structuredClone(c);for(const bad of [{...restore,hp:'heal'},{...restore,activity:'resume'},{...restore,cooldowns:'wall-clock'}])assert.throws(()=>createConfiguredRestorePolicy(bad,configured.catalog),/world-config/);assert.throws(()=>prepareRestore(c,-1,createConfiguredRestorePolicy(restore,configured.catalog)));assert.throws(()=>prepareRestore(c,Number.MAX_SAFE_INTEGER,createConfiguredRestorePolicy({...restore,history:'elapse'},configured.catalog)),/invalid-checkpoint/);assert.deepEqual(c,before);});
test('configured visibility applies personal NPC flags and reuses shared actual observation projection',()=>{const entry=configured.catalog.get('w4'),visible=createConfiguredVisibility(configured.catalog),viewer={quests:{chapter:4},flags:{}};assert.equal(visible({kind:'npc',npcId:'mira'},viewer),true);assert.equal(visible({kind:'npc',npcId:'mira'},{...viewer,flags:{frostCleared:true}}),false);assert.equal(visible({kind:'freed',npcId:'mira'},{...viewer,flags:{frostCleared:true}}),true);assert.ok(entry.publicDefinition.npcs.find(n=>n.id==='mira'));assert.equal(typeof projectObservationExtras,'function');});
test('invalid config and corrupted/missing/oversized manifest artifacts fail before any PG ownership connection',async()=>{
 let connects=0;const instrumented=new Proxy(pool,{get(target,key){if(key==='connect')return async(...args)=>{connects++;return target.connect(...args);};const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;}});await assert.rejects(startConfiguredWorld(options({pool:instrumented,config:{}})),/world-config/);assert.equal(connects,0);
 for(const mutate of [async u=>rm(new URL('world-manifest.json',u)),async u=>writeFile(new URL('world-manifest.json',u),'{}'),async u=>{const f=new URL('collision-w4.json',u);await writeFile(f,Buffer.concat([await readFile(f),Buffer.from(' ')]));},async u=>{const f=new URL('world-manifest.json',u),m=JSON.parse(await readFile(f));m.artifacts.w2.file='../collision-w2.json';await writeFile(f,JSON.stringify(m));}]){const tmp=await makeAssets();try{await mutate(tmp.url);await assert.rejects(startConfiguredWorld(options({pool:instrumented,assets:tmp.url})));assert.equal(connects,0);}finally{await rm(tmp.dir,{recursive:true,force:true});}}
 const tiny=config();tiny.assets.maxBakeBytes=1;await assert.rejects(startConfiguredWorld(options({pool:instrumented,config:tiny})),/world-config/);assert.equal(connects,0);const huge=config();huge.worlds.w1.fixedLevels.scrapling=Number.MAX_SAFE_INTEGER;await assert.rejects(startConfiguredWorld(options({pool:instrumented,config:huge})),/unsafe derived enemy stats/);assert.equal(connects,0);
});
test('failed actual Node host factory assembly releases the retained real PG guard',async()=>{
 const c=config();c.ownership.key='startup-factory-fault';const realTimeout=globalThis.setTimeout;let injected=false;globalThis.setTimeout=(callback,...args)=>{if(callback.name==='pump'&&new Error().stack.includes('createActualWorldHost')){injected=true;throw Error('factory-pump-fault');}return realTimeout(callback,...args);};try{await assert.rejects(startConfiguredWorld(options({config:c})),/factory-pump-fault/);}finally{globalThis.setTimeout=realTimeout;}assert.equal(injected,true);const reacquired=await acquireHostOwnership(pool,c.ownership.key);await reacquired.release();
});
test('shared admission ticket authenticates an actual Node host and binary concrete receiver preserves created appearance',async()=>{
 const accountId='g'+'1'.repeat(23),sessionKey='a'.repeat(64),expiresAt=Date.now()+60000;await pool.query('INSERT INTO accounts(username,updated,created)VALUES($1,0,0)',[accountId]);await pool.query('INSERT INTO sessions(token_hash,username,expires)VALUES($1,$2,$3)',[sessionKey,accountId,expiresAt]);const identity=selection('nightelf','female','priest'),record=await configured.characters.create(accountId,identity),ticket=admission.issue({accountId,sessionKey,expiresAt},origin).ticket,server=createServer();server.on('upgrade',configured.host.handleUpgrade);server.listen(0,'127.0.0.1');await once(server,'listening');const socket=new WebSocket(`ws://127.0.0.1:${server.address().port}/world`,{headers:{Origin:origin}});let receiver,state,error,disabledParty=false;socket.on('message',(bytes,binary)=>{try{if(!binary){const packet=JSON.parse(bytes.toString());if(packet.type==='world-bound'){const{type,...binding}=packet;receiver=new GameplayReceiver(binding,configured.gameplayCatalog);}if(packet.type==='error')error=Error(packet.code);}else{const result=receiver.accept(bytes,performance.now()/1000);if(result?.kind==='snapshot')state=result.state;if(result?.kind==='control'&&result.control.type==='error'&&result.control.code==='party-unavailable')disabledParty=true;}}catch(e){error=e;}});try{await once(socket,'open');socket.send(JSON.stringify({type:'authenticate',ticket,characterId:record.characterId}));await until(()=>state||error);if(error)throw error;assert.equal(state.self.player.xp,0);assert.deepEqual(state.actors.find(a=>a.ref.id===state.selfRef.id).appearance,identity.appearance);assert.ok(configured.host.stats().snapshots>=1);socket.send(encodeInput({binding:{session:state.header.session,area:state.header.area,epoch:state.header.epoch,catalog:state.header.catalog},intent:{seq:1,forward:0,strafe:0,turn:0,sprint:false,steeringYaw:null,heldChannel:null,commands:[{kind:'partyCreate'}]}},configured.gameplayCatalog));await until(()=>disabledParty||error);if(error)throw error;assert.equal(disabledParty,true);await assert.rejects(admission.consume(ticket,origin));}finally{socket.close();await until(()=>socket.readyState===WebSocket.CLOSED);server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}
});

test('optional character slot policy has no approved default and strictly validates an explicit cap',()=>{const raw=config();assert.equal(validateWorldConfig(raw).characters,undefined);raw.characters={};assert.deepEqual(validateWorldConfig(raw).characters,{});raw.characters={maxCharactersPerAccount:2};assert.deepEqual(validateWorldConfig(raw).characters,{maxCharactersPerAccount:2});for(const invalid of [0,-1,1.5,null,'2',Number.MAX_SAFE_INTEGER+1]){raw.characters={maxCharactersPerAccount:invalid};assert.throws(()=>validateWorldConfig(raw),/characters/);}raw.characters={unknown:2};assert.throws(()=>validateWorldConfig(raw));});
