test('nearby-slots-v1 requires every pool/radius/base/max/scale/respawn parameter and deterministically selects bounded origin slots',async()=>{
 const{createWorld1Definition}=await import('../../src/sim/areas/world1.ts'),valid=validateWorldConfig(nearbyConfig()),region=valid.worlds.w1,policy=createConfiguredAreaPolicy(region),definition=createWorld1Definition({...region,query:configured.catalog.get('w1').query}),slots=definition.enemies;assert.equal(slots.length,3);assert.deepEqual(slots.map(s=>policy.enemyPopulation(s,0).desired),[1,0,0]);assert.deepEqual(slots.map(s=>policy.enemyPopulation(s,1).desired),[1,1,0]);assert.deepEqual(slots.map(s=>policy.enemyPopulation(s,100).desired),[1,1,1]);assert.ok(slots.every(s=>policy.populationRadius(s)===50));assert.throws(()=>policy.enemyPopulation({...slots[0],legacySlot:'e19'},1),/origin slot/);for(const change of [r=>delete r.nearby,r=>delete r.nearby.scrapling.scale,r=>r.nearby.scrapling.max=4,r=>r.nearby.scrapling.base=4,r=>r.nearby.scrapling.scale=-1,r=>r.nearby.scrapling.radius=22,r=>r.nearby.echo.max=2,r=>delete r.respawnSeconds.scrapling]){const c=nearbyConfig();change(c.worlds.w1);assert.throws(()=>validateWorldConfig(c),/world-config/);}const fixed=config();fixed.worlds.w1.nearby=nearbyConfig().worlds.w1.nearby;assert.throws(()=>validateWorldConfig(fixed),/nearby requires/);
});
async function dynamicArea(world='w1',mutate=()=>{}){const c=nearbyConfig();mutate(c.worlds[world]);const region=validateWorldConfig(c).worlds[world],loaded=configured.catalog.get(world),{createWorld1Definition}=await import('../../src/sim/areas/world1.ts'),{createWorld2Definition}=await import('../../src/sim/areas/world2.ts'),{createWorld3Definition}=await import('../../src/sim/areas/world3.ts'),{createWorld4Definition}=await import('../../src/sim/areas/world4.ts'),definition=({w1:createWorld1Definition,w2:createWorld2Definition,w3:createWorld3Definition,w4:createWorld4Definition}[world])({...region,query:loaded.query,personalProps:{heightAt:loaded.query.heightAt,resolveCollision:(x,z,r,out)=>loaded.query.collision.resolve(x,z,r,out)}}),area=createArea({id:`dynamic-${world}-${++dynamicSerial}`,definition,query:loaded.query,policy:createConfiguredAreaPolicy(region),seed:region.seed,actionData:loaded.actionData,context:{mode:'public',pvp:'disabled',members:[]},limits:{eventCount:100000,inputCommandsPerTick:32,timers:1000,projectiles:1000}});return area;}
