async function frontierAccount(runtime,index){const accountId='g'+String(index).padStart(23,'0'),sessionKey=String(index).padStart(64,'0'),expiresAt=Date.now()+120000;await pool.query('INSERT INTO accounts(username,updated,created)VALUES($1,0,0)',[accountId]);await pool.query('INSERT INTO sessions(token_hash,username,expires)VALUES($1,$2,$3)',[sessionKey,accountId,expiresAt]);return{accountId,binding:{accountId,sessionKey,expiresAt},record:await runtime.characters.create(accountId,selection('human','female','mage'))};}
async function frontierClient(runtime,server,account){const socket=new WebSocket(`ws://127.0.0.1:${server.address().port}/world`,{headers:{Origin:origin}}),bot={socket,binding:null,state:null,seq:0,errors:[],controls:[]};socket.on('message',(bytes,binary)=>{try{if(!binary){const message=JSON.parse(bytes.toString());if(message.type==='world-bound'){const{type,...binding}=message;bot.binding=binding;bot.seq=0;bot.receiver=new GameplayReceiver(binding,runtime.gameplayCatalog);}else bot.controls.push(message);}else{const result=bot.receiver.accept(bytes,performance.now()/1000);if(result?.kind==='snapshot')bot.state=result.state;else if(result?.kind==='control')bot.controls.push(result.control);}}catch(error){bot.errors.push(error.message);}});await once(socket,'open');socket.send(JSON.stringify({type:'authenticate',ticket:admission.issue(account.binding,origin).ticket,characterId:account.record.characterId}));await until(()=>bot.state||bot.errors.length);assert.deepEqual(bot.errors,[]);bot.send=commands=>socket.send(encodeInput({binding:bot.binding,intent:{seq:++bot.seq,forward:0,strafe:0,turn:0,sprint:false,steeringYaw:null,heldChannel:null,commands}},runtime.gameplayCatalog));return bot;}
// The fixture rewrites the stored checkpoint, so it first waits for a save round that starts after the progress shown so far
// (retained saves are batched once per checkpointIntervalMs while the world keeps running).
async function afterSave(runtime){const next=runtime.host.stats().persistenceBarriers+1;await until(()=>runtime.host.stats().persistenceBarriers>=next&&!runtime.host.stats().durableBarrier);}
async function frontierFixture(runtime,bot,account,mutate){await afterSave(runtime);const epoch=bot.binding.epoch;let written=false;for(let attempt=0;attempt<10&&!written;attempt++){const current=await runtime.characters.getOwned(account.accountId,account.record.characterId),checkpoint=structuredClone(current.checkpoint);mutate(checkpoint);try{await runtime.characters.saveCheckpoint(account.accountId,account.record.characterId,current.revision,checkpoint,[]);written=true;}catch(error){if(error.code!=='conflict')throw error;}}assert(written);await until(()=>bot.binding.epoch>epoch&&bot.state.header.epoch===bot.binding.epoch||bot.errors.length);assert.deepEqual(bot.errors,[]);}
function frontierLocation(checkpoint,loaded,point){const out={x:0,y:0,set(x,y){this.x=x;this.y=y;return this;}};loaded.query.resolveCollision(point.x,point.z,loaded.actionData.archetype('human').radius,out);checkpoint.location={x:out.x,y:loaded.query.heightAt(out.x,out.y),z:out.y,yaw:0};}

test('explicit six-world actual PG/WS host preserves gate prerequisites, chapter/tracking, cooldown and reconnect progress', {timeout:30000},async()=>{
 const packaged=await makeAssets([...worlds,'w5','w6']);let runtime,server,bot;
 try{const c=frontierConfig();c.ownership.key='six-world-travel';runtime=await startConfiguredWorld(options({assets:packaged.url,config:c}));assert.equal(runtime.host.stats().publicAreas,6);assert(runtime.gameplayCatalog.archetypes.includes('boss-ember'));assert(runtime.gameplayCatalog.archetypes.includes('boss-sky'));const account=await frontierAccount(runtime,41),initial=structuredClone(account.record.checkpoint),w4=runtime.catalog.get('w4'),gate=w4.publicDefinition.interactions.find(i=>i.id==='gate:w5');
  // Trusted region/position fixture only. No XP, coins or unlock are supplied by clients or runtime startup.
  initial.world='w4';setQuestChapter(initial.progress.quests,4);frontierLocation(initial,w4,gate.position);account.record=await runtime.characters.saveCheckpoint(account.accountId,account.record.characterId,account.record.revision,initial,[]);
  server=createServer();server.on('upgrade',runtime.host.handleUpgrade);server.listen(0,'127.0.0.1');await once(server,'listening');bot=await frontierClient(runtime,server,account);bot.send([{kind:'travel',gateId:'gate:w5'}]);await until(()=>bot.receiver.header.consumedInput>=1);assert.equal(bot.state.world,'w4');assert.equal(bot.state.self.player.xp,0);
  await frontierFixture(runtime,bot,account,checkpoint=>{checkpoint.progress.flags.frostCleared=true;checkpoint.progress.flags.finalCleared=true;});bot.send([{kind:'ability',slot:5}]);await until(()=>bot.state.self.player.cooldowns['crown-burst']);let durableCooldown=false;for(let i=0;i<150&&!durableCooldown;i++){durableCooldown=!!(await runtime.characters.getOwned(account.accountId,account.record.characterId)).checkpoint.survival.cooldowns['crown-burst'];if(!durableCooldown)await delay(20);}assert(durableCooldown,'cooldown must be saved before the trusted navigation CAS fixture');
  for(const[from,to]of[['w4','w5'],['w5','w6'],['w6','w5'],['w5','w4']]){const loaded=runtime.catalog.get(from),point=loaded.publicDefinition.interactions.find(i=>i.id===`gate:${to}`);await frontierFixture(runtime,bot,account,checkpoint=>frontierLocation(checkpoint,loaded,point.position));const epoch=bot.binding.epoch;bot.send([{kind:'travel',gateId:`gate:${to}`}]);await until(()=>bot.state.world===to&&bot.binding.epoch>epoch||bot.errors.length).catch(error=>{throw Error(`${from}->${to}: ${error.message}; actual=${bot.state.world}; controls=${JSON.stringify(bot.controls)}`);});assert.deepEqual(bot.errors,[]);assert.equal(bot.state.self.player.quests.chapter,Number(to[1]));assert.equal(Object.keys(bot.state.self.player.quests.status).length,59);assert.equal(bot.state.self.player.xp,0);assert.equal(bot.state.self.player.coins,0);assert(bot.state.self.player.cooldowns['crown-burst'].end>bot.state.time+20);assert.equal(bot.state.features.environment.mode,'public');assert.equal(bot.state.features.environment.pvp,'disabled');if(to==='w5'||to==='w6'){const questId=to==='w5'?'r5q2':'r6q2';bot.send([{kind:'questTrack',questId}]);await until(()=>bot.state.self.player.quests.tracked[Number(to[1])]===questId);}}
  const saved=await runtime.characters.getOwned(account.accountId,account.record.characterId);assert.equal(saved.checkpoint.world,'w4');assert.equal(saved.checkpoint.progress.quests.tracked[5],'r5q2');assert.equal(saved.checkpoint.progress.quests.tracked[6],'r6q2');assert.equal(saved.checkpoint.progress.xp,0);bot.socket.close();await until(()=>bot.socket.readyState===WebSocket.CLOSED);bot=await frontierClient(runtime,server,account);assert.equal(bot.state.self.player.quests.tracked[5],'r5q2');assert.equal(bot.state.self.player.quests.tracked[6],'r6q2');assert.equal(bot.state.self.player.xp,0);assert.equal(runtime.host.stats().publicAreas,6);
 }finally{bot?.socket.close();if(bot)await until(()=>bot.socket.readyState===WebSocket.CLOSED);await runtime?.host.shutdown(3000);if(server){server.closeAllConnections();await new Promise(r=>server.close(r));}await runtime?.ownership.release();await rm(packaged.dir,{recursive:true,force:true});}
});

